INSERT INTO public.virtual_bot_matchup_prompts
  (category_id, title, description, body_text, tags, image_prompt)
VALUES
  ('eternal_quest', '카공 콘센트, 먼저 꽂는 게 맞음?', '난 앉자마자 충전기부터 꽂는 게 생존이라고 봄. 눈치 보다 방전되는 거 손해. 양보파 나와봐.', '카공은 콘센트가 자리값임. 음료는 그 자리에 대한 입장권임.', ARRAY['카공','콘센트','매너'], 'A Korean woman in her early 20s plugging a charger into a cafe wall outlet as she sits down, laptop closed, candid'),
  ('eternal_quest', '중고거래 네고, 예의임 실례임?', '난 시세 보고 한 번 묻는 건 예의라고 봄. 터무니없이 깎자는 건 시간 도둑임. 정가파 반박해봐.', '네고는 한 번이면 충분함. 세 번 깎으면 그 거래는 이미 불편해짐.', ARRAY['중고','네고','매너'], 'A Korean man in his early 20s photographing a small used item on a desk before a meetup, natural light'),
  ('eternal_quest', '새벽 배송 소리, 참는 게 맞음?', '난 새벽에 문 앞 소음은 한 번 말하는 게 맞다고 봄. 그냥 참는 게 어른이라는 쪽 들어와.', '새벽 소음은 편리의 뒷면임. 한 번 요청이 층간 감정보다 깔끔함.', ARRAY['배송','소음','자취'], 'A Korean woman in her early 20s glancing at her apartment door at dawn, a small parcel outside, sleepy'),
  ('eternal_quest', '에어컨 온도, 누가 맞추는 게 맞음?', '난 더위 타는 사람 기준으로 맞추고 겉옷을 더하는 게 맞다고 봄. 추위파 논리 가져와.', '온도는 다수결이 아니라 못 버티는 쪽임. 겉옷은 개인이 해결함.', ARRAY['에어컨','온도','자취'], 'A Korean man in his early 20s adjusting a small air conditioner remote in a shared room, light jacket on a chair'),
  ('eternal_quest', '분리수거, 하루 미뤄도 됨?', '난 당일 버리는 게 방이 안 죽는 길이라고 봄. 모아서 한 번에가 효율이라는 사람 나와봐.', '분리수거는 미루는 순간 현관이 창고가 됨. 당일이 제일 짧음.', ARRAY['분리수거','자취','습관'], 'A Korean woman in her early 20s sorting recycling into bags by an apartment door, evening, casual clothes'),
  ('eternal_quest', '도서관 가방 맡기기, 매너임?', '난 자리 비울 거면 가방도 가져가는 게 맞다고 봄. 잠시 맡김은 관례라는 쪽 반박해봐.', '가방 맡기기는 자리 독임. 화장실도 표시 없이 오래면 양보가 맞음.', ARRAY['도서관','자리','매너'], 'A Korean man in his early 20s picking up his backpack from a library seat before stepping away, quiet room'),
  ('eternal_quest', '헬스장 기구, 쉬는 시간 한 세트가 끝임?', '난 세트 사이에 폰 보면 줄이 생긴다고 봄. 휴식도 운동이라는 사람 논리 들어봄.', '기구는 점유가 아니라 교대임. 한 세트 끝나면 눈이 마주친 사람한테 넘김.', ARRAY['헬스','기구','매너'], 'A Korean woman in her early 20s stepping back from a gym machine to let someone else start, ordinary gym, no logos'),
  ('eternal_quest', '단체 메뉴, 다수결이 맞음?', '난 못 먹는 사람 하나면 그 집은 빼는 게 맞다고 봄. 다수결이 민주주의라는 쪽 나와봐.', '메뉴는 표수가 아니라 제외 조건임. 한 명이 못 먹으면 그 모임이 불편해짐.', ARRAY['모임','메뉴','배려'], 'Young Korean people in their early 20s looking at one phone menu at a restaurant entrance, deciding together'),
  ('eternal_quest', '우산 안 빌려주는 거, 매정임?', '난 우산은 빌려주면 돌아오지 않는 물건이라고 봄. 비 맞히는 게 매정이라는 사람 들어와.', '우산은 호의 한 번이면 됨. 기대하고 빈손으로 나오는 게 더 부담임.', ARRAY['우산','호의','매너'], 'A Korean man in his early 20s hesitating at a doorway with one umbrella while rain hits the street'),
  ('eternal_quest', '필기는 손글씨가 더 남음?', '난 손으로 적어야 시험 전에 기억이 난다고 봄. 타자가 빠르다는 쪽 논리 가져와.', '손글씨는 느린 게 아니라 한 번 더 읽는 거임. 받아쓰기 속도만 보면 짐.', ARRAY['필기','공부','습관'], 'A Korean woman in her early 20s writing in a notebook at a library desk, phone face down, daylight'),
  ('eternal_quest', '공유 오피스, 카페보다 이득임?', '난 시간당 내는 자리가 눈치 없는 집중이라고 봄. 카페 음료가 더 싸다는 사람 반박해봐.', '공유 오피스는 자리 임대임. 카페는 두 잔째부터 민망해짐.', ARRAY['공유오피스','집중','카공'], 'A Korean man in his early 20s working at a quiet shared desk with a laptop, ordinary coworking corner, no logos'),
  ('eternal_quest', '카풀 기름값, 따로 내는 게 맞음?', '난 탈 때마다 기름값을 보내는 게 우정이라고 봄. 운전한 정이 크다는 쪽 나와봐.', '카풀은 호의가 기본값이 아님. 금액이 적어야 다음에도 태워줌.', ARRAY['카풀','기름값','정산'], 'A Korean woman in her early 20s in a passenger seat sending a small transfer, driver friend looking ahead, daytime'),
  ('eternal_quest', '택배 박스, 당일 치우는 게 매너임?', '난 박스는 받은 날 버리는 게 현관 매너라고 봄. 분리수거 날까지 모아도 된다는 쪽 들어와.', '박스는 선물이 아니라 부피임. 하루만 쌓여도 복도가 좁아짐.', ARRAY['택배','박스','자취'], 'A Korean man in his early 20s flattening a cardboard box in a small entryway, tidy apartment'),
  ('eternal_quest', '친구 집, 양말 신고 들어가도 됨?', '난 주인이 신으라고 하기 전에 벗는 게 기본이라고 봄. 양말이 예의라는 사람 반박해봐.', '신발이 끝나면 양말도 눈치임. 물어보는 한 마디가 바닥을 지킴.', ARRAY['방문','양말','예절'], 'A Korean woman in her early 20s pausing at a friend apartment entrance, shoes off, looking at the floor'),
  ('fashion', '옷 수선, 새로 사는 것보다 이득임?', '난 기장 수선이 새 옷 한 벌보다 핏을 살린다고 봄. 수선집에 갈 시간에 산다는 쪽 나와봐.', '수선은 귀찮음이 아니라 옷 수명임. 안 맞는 새 옷이 더 비쌈.', ARRAY['수선','핏','가성비'], 'A Korean woman in her early 20s holding a hemmed pair of trousers up in a small room, mirror nearby'),
  ('fashion', '같은 옷 반복, 게으름임 시그니처임?', '난 매일 비슷한 조합이 실패를 줄인다고 봄. 매일 달라야 패션이라는 사람 논리 들어봄.', '반복은 게으름이 아니라 유니폼임. 잘 맞는 한 벌이 아침을 줄임.', ARRAY['반복','유니폼','코디'], 'A Korean man in his early 20s wearing the same simple jacket and tee, weekday sidewalk, candid'),
  ('fashion', '후드티, 외출복으로 됨?', '난 깨끗한 후드가 약속 장소까지 커버된다고 봄. 카라가 있어야 외출이라는 쪽 들어와.', '후드는 잠옷이 아님. 신발만 정돈되면 저녁 약속도 됨.', ARRAY['후드','외출','캐주얼'], 'A Korean woman in her early 20s walking to a cafe in a clean hoodie and sneakers, evening street'),
  ('fashion', '컬러 양말, 포인트임 과함임?', '난 양말 색깔 하나가 전신을 살린다고 봄. 눈에 띄면 과하다는 사람 반박해봐.', '양말은 숨기는 옷이 아님. 바지 밑으로 한 줄이 코디의 마침표임.', ARRAY['양말','포인트','코디'], 'A Korean man in his early 20s sitting on a bench, a bright sock showing above a simple sneaker, candid'),
  ('fashion', '계절 옷 정리, 꼭 해야 함?', '난 한 철 지난 옷을 상자 넣는 날이 옷장 리셋이라고 봄. 꺼내 입으면 된다는 쪽 나와봐.', '정리는 행사임. 안 하면 아침마다 여름 옷이 겨울을 막음.', ARRAY['정리','옷장','계절'], 'A Korean woman in her early 20s folding off-season clothes into a box on the floor, closet open'),
  ('fashion', '카라 티, 일상에도 맞음?', '난 카라 티가 후드보다 약속 범위가 넓다고 봄. 편하려면 라운드만 입자는 사람 들어와.', '카라는 딱딱함이 아니라 외출 스위치임. 청바지랑 입으면 과하지 않음.', ARRAY['카라티','일상','코디'], 'A Korean man in his early 20s in a plain polo and jeans at a casual lunch table, no logos'),
  ('fashion', '와이드 팬츠, 아직도 편함 이김?', '난 와이드가 앉는 하루를 편하게 한다고 봄. 슬림이 정리돼 보인다는 쪽 논리 가져와.', '밑단이 넓어도 허리가 맞으면 정돈임. 편해야 오후에 표정이 남음.', ARRAY['와이드','팬츠','편함'], 'A Korean woman in her early 20s walking in wide trousers and a simple tee, Seoul crosswalk, candid'),
  ('fashion', '코트 하나, 겨울이 커버됨?', '난 무겁지 않은 코트 하나가 패딩 여러 벌보다 낫다고 봄. 길이별로 있어야 한다는 사람 나와봐.', '코트는 개수가 아니라 기장임. 매일 입을 하나가 진짜 겨울옷임.', ARRAY['코트','겨울','기본템'], 'A Korean man in his early 20s buttoning one simple coat at an apartment door, winter light, no logos'),
  ('fashion', '실내화, 따로 두는 게 패션임?', '난 밖에서 신은 신발을 방에 안 들이는 게 코디의 시작이라고 봄. 귀찮다는 쪽 반박해봐.', '실내화는 위생이자 집 옷임. 운동화 그대로면 방이 거리랑 같아짐.', ARRAY['실내화','집','습관'], 'A Korean woman in her early 20s switching to plain house slippers at the entrance, outdoor shoes set aside'),
  ('fashion', '모자, 로고 없는 게 맞음?', '난 글자 없는 모자가 얼굴이 산다고 봄. 로고가 포인트라는 사람 논리 들어봄.', '모자는 그늘이지 간판이 아님. 심플해야 어떤 옷에도 붙음.', ARRAY['모자','심플','코디'], 'A Korean man in his early 20s wearing a plain unbranded cap on a sunny street, natural face'),
  ('fashion', '옷 사진 찍고 사기, 실패를 줄임?', '난 피팅 사진을 다음날 다시 보는 게 충동을 거른다고 봄. 즉석 결제가 감각이라는 쪽 나와봐.', '사진은 인증이 아니라 쿨링임. 하루 지나도 갖고 싶으면 그때 삼.', ARRAY['피팅','쇼핑','충동'], 'A Korean woman in her early 20s taking a mirror photo of an outfit in a fitting room, deciding, no logos'),
  ('fashion', '니트는 한 장만 있어도 됨?', '난 색 하나 잘 받는 니트가 겨울 상의를 대체한다고 봄. 패턴 니트 수집파 들어와.', '니트는 종류보다 목선임. 매일 입는 한 장이 옷장 주인공임.', ARRAY['니트','겨울','기본템'], 'A Korean man in his early 20s pulling on a plain knit sweater at home, morning, soft light'),
  ('fashion', '벨트, 아직도 필요한 아이템임?', '난 허리만 잡아줘도 실루엣이 산다고 봄. 밴딩이면 충분하다는 사람 반박해봐.', '벨트는 포멀용이 아니라 비율임. 늘어진 허리만 잡아도 다른 옷이 됨.', ARRAY['벨트','실루엣','코디'], 'A Korean woman in her early 20s fastening a simple belt over trousers, bedroom mirror, candid'),
  ('맛집', '익선동 골목, 줄보다 분위기가 탐방임?', '난 익선은 줄 선 집보다 골목 공기가 탐방이라고 봄. 웨이팅이 그 동네라는 쪽 나와봐.', '한옥 골목은 자리보다 걷는 시간이 남음. 줄만 서면 어느 동네든 같아짐.', ARRAY['익선동','골목','탐방'], 'A Korean woman in her early 20s walking a narrow hanok alley in Ikseon-dong, looking at small shopfronts'),
  ('맛집', '한남 언덕집, 뷰가 탐방값임?', '난 먹고 내려다보는 자리가 그 집 이유라고 봄. 음식만 보면 된다는 사람 논리 가져와.', '언덕집은 동선이 메뉴임. 뷰가 없는데 힘들어서 오른 거면 다음엔 안 감.', ARRAY['한남','뷰','탐방'], 'A Korean man in his early 20s sitting by a hillside window after a meal, city view, relaxed'),
  ('맛집', '화장실 깨끗한 집, 재방문 이유 됨?', '난 화장실이 그 집 관리라고 봄. 맛있으면 상관없다는 쪽 반박해봐.', '화장실은 숨은 서비스임. 한 번 불편하면 그 골목이 식음.', ARRAY['화장실','서비스','재방문'], 'A Korean woman in her early 20s washing her hands in a small clean restaurant restroom, ordinary, candid'),
  ('맛집', '오픈 키친, 그 집 구경거리임?', '난 불이 보이는 집이 탐방 재미라고 봄. 자리는 조용해야 한다는 사람 들어와.', '오픈 키친은 쇼가 아니라 신뢰임. 손이 보이면 대기가 덜 지루함.', ARRAY['오픈키친','분위기','탐방'], 'A Korean man in his early 20s watching cooks at an open kitchen counter, small restaurant, interested'),
  ('맛집', '루프탑 자리, 탐방에 넣어도 됨?', '난 올라가서 먹는 한 끼가 그 동네 기억이라고 봄. 바람 불면 실내가 진리라는 쪽 나와봐.', '루프탑은 사진용이 아니라 저녁 공기임. 맛까지 되면 그 집이 남음.', ARRAY['루프탑','저녁','탐방'], 'Two Korean people in their early 20s at a simple rooftop table at dusk, city behind them, no logos'),
  ('맛집', '골목 포장마차, 매장보다 그 지역임?', '난 포장 천막이 그 동네 밤 온도라고 봄. 의자가 있어야 탐방이라는 사람 반박해봐.', '포장마차는 간이 아님. 서서 먹는 그 블록이 지역임.', ARRAY['포장마차','골목','밤'], 'A Korean woman in her early 20s standing at a small street stall at night, steam, casual clothes'),
  ('맛집', '백화점 맛집층, 탐방 동선임?', '난 비 오는 날 백화점 층이 탐방 대체 루트라고 봄. 길거리만 탐방이라는 쪽 들어와.', '백화점 층은 가짜 골목이 아님. 여러 집을 날씨 없이 비교하는 동선임.', ARRAY['백화점','맛집층','동선'], 'A Korean man in his early 20s walking a department-store food floor, looking at stall signs, rainy day clothes'),
  ('맛집', '역에서 10분, 그 거리가 탐방임?', '난 출구에서 걷는 10분이 그 집을 고르는 이유라고 봄. 역세권만 진리라는 사람 나와봐.', '가까운 집은 편리지 탐방이 아님. 골목 하나 더 들어가야 지역이 보임.', ARRAY['역세권','도보','탐방'], 'A Korean woman in her early 20s walking ten minutes from a subway exit toward a small restaurant, map on phone'),
  ('맛집', '사장님이 자리 안내, 그 집이 급임?', '난 주문 전에 자리를 봐 주는 집이 다시 간다고 봄. 셀프가 빠르다는 쪽 논리 들어봄.', '안내는 격식이 아니라 동선임. 서서 헤매면 그 집 첫인상이 김.', ARRAY['안내','서비스','맛집'], 'A Korean restaurant owner in their 40s gesturing a young Korean guest in their early 20s toward an open table'),
  ('맛집', '테라스 자리, 실내보다 그 집임?', '난 바깥 테이블이 그 카페를 온 이유라고 봄. 에어컨 실내가 진리라는 사람 반박해봐.', '테라스는 계절 한정 메뉴임. 자리 없으면 다른 날이 맞음.', ARRAY['테라스','카페','자리'], 'A Korean man in his early 20s sitting at a small terrace table with an iced drink, shade, candid'),
  ('맛집', '라스트 오더, 탐방 일정에 넣음?', '난 마지막 주문 시간을 보고 집을 고른다고 봄. 문 닫기 직전이 낭만이라는 쪽 나와봐.', '라스트 오더는 마감 독촉임. 여유 있게 앉는 집이 재방문됨.', ARRAY['라스트오더','시간','탐방'], 'A Korean woman in her early 20s checking a restaurant closing time on the door, early evening'),
  ('맛집', '메뉴판 없는 집, 탐방 모험임?', '난 오늘 나온 것만 내는 집이 지역 탐방이라고 봄. 메뉴가 있어야 안심이라는 사람 들어와.', '메뉴판 없음은 불친절이 아니라 그날의 재료임. 못 먹으면 미리 말하면 됨.', ARRAY['메뉴','노포','탐방'], 'A Korean man in his early 20s listening as a server describes today dishes, small restaurant, no menu board'),
  ('맛집', '동네 단골집, 핫플보다 실력임?', '난 이름 없는 단골이 탐방의 끝이라고 봄. 새로 연 집만 기록이라는 쪽 반박해봐.', '단골은 인증이 아니라 반복임. 세 번 간 집이 그 사람 지도임.', ARRAY['단골','동네','탐방'], 'A Korean woman in her early 20s being recognized by staff at a small neighborhood restaurant, warm candid'),
  ('맛식', '식빵 가장자리, 그 식감이 맛임?', '난 껍질 쪽이 식빵의 이유라고 봄. 부드러운 속만 진리라는 사람 나와봐.', '가장자리는 태운 게 아니라 씹는 맛임. 속만 먹으면 다음 장이 싱거움.', ARRAY['식빵','식감','맛'], 'A Korean man in his early 20s eating a toast crust at a small breakfast table, butter nearby'),
  ('맛식', '아이스 아메리카노, 연해야 맛임?', '난 연한 아이스가 오래 마신다고 봄. 진해야 커피라는 쪽 논리 가져와.', '쓴맛 농도는 취향이 아니라 속도임. 너무 진하면 반 잔에 끝남.', ARRAY['아메리카노','커피','맛'], 'A Korean woman in her early 20s sipping a light iced coffee at a window seat, relaxed'),
  ('맛식', '김치 익은 맛, 이게 진리임?', '난 살짝 익은 김치가 밥이랑 제일 맞는다고 봄. 갓 담근 아삭파 반박해봐.', '익은 김치는 향이 맛임. 너무 일찍 먹으면 짠맛만 남음.', ARRAY['김치','발효','맛'], 'A Korean man in his early 20s taking ripe kimchi with rice, home table, close candid'),
  ('맛식', '소스 따로, 튀김 식감이 삼?', '난 소스를 따로 둬야 튀김이 끝까지 산다고 봄. 뿌려야 맛이라는 사람 들어와.', '소스는 선택임. 처음부터 적시면 마지막 한 입이 다른 음식이 됨.', ARRAY['튀김','소스','식감'], 'A Korean woman in her early 20s dipping one piece of fried food, sauce in a small dish beside the plate'),
  ('맛식', '라면 스프 반, 간이 맛임?', '난 스프를 반만 넣는 게 국물의 여운이라고 봄. 전부 넣어야 라면이라는 쪽 나와봐.', '반은 싱거움이 아니라 조절임. 면이 스프를 더 먹으면 끝이 짜짐.', ARRAY['라면','간','맛'], 'A Korean man in his early 20s pouring only part of a ramen soup packet into a pot, small kitchen'),
  ('맛식', '초밥은 밥 온도가 맛임?', '난 밥이 살짝 따뜻해야 그 초밥이라고 봄. 생선만 보자는 사람 논리 들어봄.', '밥 온도는 간임. 차가우면 식초가 먼저 남음.', ARRAY['초밥','밥','온도'], 'A Korean woman in her early 20s lifting a piece of sushi, rice visible, small counter seat'),
  ('맛식', '튀김옷 얇은 게 맛임?', '난 옷이 얇아야 재료가 보인다고 봄. 두꺼운 바삭이 진리라는 쪽 반박해봐.', '얇은 옷은 겸손이 아니라 식감 배분임. 옷만 먹으면 재료가 짐.', ARRAY['튀김옷','식감','맛'], 'A Korean man in his early 20s breaking a lightly battered fried piece, filling visible, casual table'),
  ('맛식', '디저트는 쓴맛이 있어야 함?', '난 마지막에 쓴맛이 단맛을 끊는다고 봄. 달아야 디저트라는 사람 나와봐.', '쓴맛은 어른 취향 자랑이 아님. 한 입 리셋이 다음 조각을 가능하게 함.', ARRAY['디저트','쓴맛','맛'], 'A Korean woman in her early 20s tasting a bitter chocolate dessert, thoughtful smile, cafe'),
  ('맛식', '국수 육수, 멸치가 기본임?', '난 멸치 육수가 국수의 바닥이라고 봄. 고기 육수가 진리라는 쪽 들어와.', '멸치는 구수함임. 고기만 있으면 면이 무거워짐.', ARRAY['국수','육수','멸치'], 'A Korean man in his early 20s eating noodles in a clear anchovy broth, steam, small shop'),
  ('맛식', '에어프라이어, 튀김 맛이 남?', '난 에어가 튀김의 바삭을 집에서도 만든다고 봄. 기름 튀김만 진짜라는 사람 반박해봐.', '에어는 타협이 아니라 온도임. 겉이 서면 그 식감은 남음.', ARRAY['에어프라이어','튀김','식감'], 'A Korean woman in her early 20s taking crispy food from an air fryer in a small kitchen, pleased'),
  ('맛식', '과일 먼저, 식단이 더 맛있음?', '난 식사 전에 과일이 단맛 폭주를 줄인다고 봄. 식후 과일이 진리라는 쪽 나와봐.', '과일은 디저트 순서가 아니라 첫 단맛임. 먼저 먹으면 다음 끼가 덜 달아짐.', ARRAY['과일','식단','순서'], 'A Korean man in his early 20s eating sliced fruit before a meal, small plate, home table'),
  ('맛식', '견과 한 줌, 간식 맛으로 됨?', '난 견과가 과자보다 한 끼 사이를 버틴다고 봄. 달콤해야 간식이라는 사람 논리 가져와.', '견과는 건강 숙제가 아니라 고소함임. 짜면 한 줌에서 끝남.', ARRAY['견과','간식','맛'], 'A Korean woman in her early 20s eating a small handful of nuts at a desk, afternoon, not posed'),
  ('맛식', '물김치, 밥도둑 맛임?', '난 물김치 국물이 밥 한 공기를 끝낸다고 봄. 겉절이 아삭이 진리라는 쪽 반박해봐.', '물김치는 국이 아님. 시원한 한 술이 간을 리셋함.', ARRAY['물김치','밥','맛'], 'A Korean man in his early 20s spooning watery kimchi broth over rice, summer table, candid'),
  ('맛식', '냉면 육수, 심심해야 맛임?', '난 냉면은 밍밍한 듯해야 면이 산다고 봄. 진한 육수파 나와봐.', '심심함은 실패가 아니라 온도임. 짜면 중간에 물을 찾게 됨.', ARRAY['냉면','육수','맛'], 'A Korean woman in her early 20s tasting cold noodle broth with chopsticks lifted, summer restaurant'),
  ('lifestyle', '일기, 아직도 쓸 가치 있음?', '난 세 줄 일기가 하루를 닫는다고 봄. 기록은 사진이면 된다는 사람 나와봐.', '일기는 문장이 아니라 마무리임. 안 쓰면 같은 하루가 반복처럼 남음.', ARRAY['일기','기록','습관'], 'A Korean woman in her early 20s writing three lines in a small notebook before bed, lamp light'),
  ('lifestyle', '이동은 팟캐스트가 맞음?', '난 출퇴근은 말이 있는 게 덜 지친다고 봄. 음악만 듣는다는 쪽 반박해봐.', '팟캐스트는 공부가 아니라 동행임. 한 편이 한 정거장을 짧게 함.', ARRAY['팟캐스트','출퇴근','취향'], 'A Korean man in his early 20s on a subway with earphones, calm, ordinary commute'),
  ('lifestyle', '주 1회 폰 내려놓기, 가능함?', '난 반나절만 내려놔도 주말이 길어진다고 봄. 연락이 끊긴다는 사람 논리 들어봄.', '디톡스는 자랑이 아니라 반나절임. 통째 하루는 불안만 키움.', ARRAY['디톡스','폰','주말'], 'A Korean woman in her early 20s leaving her phone in a drawer and picking up a book, Saturday afternoon'),
  ('lifestyle', '방 향초, 기분값 됨?', '난 불 하나 켜는 게 저녁을 바꾼다고 봄. 냄새 민감하다는 쪽 들어와.', '향초는 인테리어가 아니라 종료 의식임. 잠들기 전에 끄면 됨.', ARRAY['향초','저녁','방'], 'A Korean man in his early 20s lighting one small candle on a side table, evening apartment, no labels'),
  ('lifestyle', '짐 적은 방, 멘탈에 이득임?', '난 보이는 물건이 줄어야 집이 쉰다고 봄. 수납이 많아야 편하다는 사람 반박해봐.', '빈 바닥은 휑함이 아니라 동선임. 물건이 보이면 할 일이 보여서 쉼이 안 됨.', ARRAY['미니멀','방','멘탈'], 'A Korean woman in her early 20s sitting on a clear floor in a sparse room, one plant, relaxed'),
  ('lifestyle', '주말 아침 시장, 루틴으로 맞음?', '난 시장 한 바퀴가 주말 외출의 최소치라고 봄. 집 충전이 우선이라는 쪽 나와봐.', '시장은 장보기가 아니라 사람 소리임. 한 시간이면 주말이 시작됨.', ARRAY['시장','주말','루틴'], 'A Korean man in his early 20s walking a morning market with a small tote, looking at produce'),
  ('lifestyle', '보드게임, 술자리보다 남음?', '난 게임 한 판이 대화 주제를 만들어 준다고 봄. 술이 있어야 모임이라는 사람 들어와.', '보드는 승부가 아니라 자리임. 마시지 않아도 두 시간이 참.', ARRAY['보드게임','모임','취향'], 'Young Korean people in their early 20s around a low table with a board game, snacks, laughing candid'),
  ('lifestyle', '플래너 수기, 앱보다 맞음?', '난 손으로 적는 주간이 일정 체감이 크다고 봄. 알림이 플래너라는 쪽 논리 가져와.', '수기는 느린 게 아니라 한 번 더 봄. 앱은 미루기 버튼이 너무 가까움.', ARRAY['플래너','수기','일정'], 'A Korean woman in her early 20s writing a weekly plan in a paper planner, coffee beside it'),
  ('lifestyle', '산책, 운동 대신 됨?', '난 40분 걷기가 운동 출석보다 지속된다고 봄. 땀이 나야 운동이라는 사람 반박해봐.', '산책은 대충이 아니라 매일임. 기록 없는 걸음이 다음 주를 살림.', ARRAY['산책','운동','습관'], 'A Korean man in his early 20s walking a neighborhood sidewalk at dusk, ordinary jacket, no logos'),
  ('lifestyle', '계절 노래 목록, 필요한가?', '난 계절마다 목록을 바꾸는 게 기분을 구분한다고 봄. 셔플이면 된다는 쪽 나와봐.', '목록은 감성 과장이 아님. 같은 노래만 나오면 계절이 안 바뀜.', ARRAY['플레이리스트','계절','취향'], 'A Korean woman in her early 20s choosing songs on a phone by a window, autumn light, earphones in hand'),
  ('lifestyle', '중고 가구, 새 것보다 방 맛임?', '난 자국 있는 책상 하나가 방을 살린다고 봄. 새 가구여야 정돈이라는 사람 들어와.', '중고 가구는 낡음이 아니라 크기 맞춤임. 새 거 기다리다 바닥이 빔.', ARRAY['중고','가구','방'], 'A Korean man in his early 20s wiping a secondhand wooden desk in a small room, pleased'),
  ('lifestyle', '하루 한 장 사진, 기록이 됨?', '난 하루에 한 장만 찍는 게 나중에 본다고 봄. 많이 찍어야 남는다는 쪽 반박해봐.', '한 장은 제한이 아니라 선택임. 백 장은 앨범에서 안 열림.', ARRAY['사진','기록','하루'], 'A Korean woman in her early 20s taking one photo of her meal by a window, phone then set down'),
  ('lifestyle', '주말 일찍 자기, 회복임?', '난 토요일 열한 시 잠이 월요일을 살린다고 봄. 주말 밤이 본편이라는 사람 나와봐.', '일찍 자는 주말은 손해 봄이 아님. 일요일 낮이 진짜 휴식임.', ARRAY['수면','주말','회복'], 'A Korean man in his early 20s turning off a lamp and lying down on a weekend night, calm'),
  ('romance', '기념일 선물, 취향이 금액보다 큼?', '난 상대가 말한 작은 게 비싼 surprise보다 남다고 봄. 금액이 마음이라는 쪽 들어와.', '선물은 가격표가 아니라 기억임. 평소 한 마디가 포장보다 김.', ARRAY['선물','기념일','연애'], 'A Korean woman in her early 20s handing a small wrapped gift across a cafe table, partner smiling'),
  ('romance', '연락 없는 하루, 이 정도면 됨?', '난 바쁜 하루 침묵은 괜찮다고 봄. 매일 안부가 사랑이라는 사람 반박해봐.', '하루 비움은 식음이 아님. 다음 날 이유를 말하면 온도가 유지됨.', ARRAY['연락','하루','연애'], 'A Korean man in his early 20s finishing work and then opening a chat, tired but about to reply'),
  ('romance', '연애 상담, 친구에게 어디까지임?', '난 싸움 내용은 당사자끼리 두는 게 맞다고 봄. 친구 의견이 필요하다는 쪽 나와봐.', '상담은 감정까지만. 상대 험담이 되면 화해가 어려워짐.', ARRAY['상담','친구','연애'], 'A Korean woman in her early 20s talking with a friend at a cafe, serious but not dramatic, phones down'),
  ('romance', '전 애인 이야기, 해도 됨?', '난 물어보면 짧게 말하는 게 솔직이라고 봄. 과거는 닫아야 한다는 사람 논리 들어봄.', '과거는 자랑이 아님. 비교가 시작되면 그때 주제를 바꿈.', ARRAY['과거','솔직','연애'], 'A Korean man in his early 20s speaking calmly with a partner on a bench, no phones, daytime'),
  ('romance', '데이트 사진, 꼭 남겨야 함?', '난 한 장이면 충분하고 없어도 그날은 남다고 봄. 기록이 없으면 안 만난 거라는 쪽 반박해봐.', '사진은 증거가 아님. 찍느라 음식이 식으면 날짜만 남음.', ARRAY['사진','데이트','기록'], 'Two Korean people in their early 20s putting a phone away to eat, one photo already taken, casual table'),
  ('romance', '밥 취향 다르면, 데이트가 힘듦?', '난 번갈아 고르면 취향 차이가 재미라고 봄. 입맛이 같아야 오래간다는 사람 들어와.', '다른 메뉴는 양보 연습임. 매번 맞추기만 하면 한 사람이 지침.', ARRAY['밥','취향','데이트'], 'A Korean woman in her early 20s and a partner pointing at different dishes on one menu, smiling'),
  ('romance', '늦는 연락, 이유부터가 매너임?', '난 늦으면 이유 한 줄을 먼저 보내는 게 애정이라고 봄. 도착해서 말하면 된다는 쪽 나와봐.', '이유는 변명이 아니라 대기 시간임. 침묵이 제일 길게 느껴짐.', ARRAY['지각','연락','연애'], 'A Korean man in his early 20s sending a short late message on the street, apologetic, walking'),
  ('romance', '호감 티, 빨리 내는 게 맞음?', '난 좋은 티를 일찍 내는 게 서로 덜 헤맨다고 봄. 티 내면 가벼워 보인다는 사람 반박해봐.', '티는 들이댐이 아니라 방향임. 숨기면 상대는 다른 신호를 봄.', ARRAY['호감','티','썸'], 'A Korean woman in her early 20s laughing openly on a second meeting, cafe, candid warmth'),
  ('romance', '커플템, 있어야 티가 남?', '난 같은 물건 없이도 연애라고 봄. 맞춰야 공개라는 쪽 논리 가져와.', '커플템은 놀이임. 없어도 약속이 맞으면 밖에서도 보임.', ARRAY['커플템','공개','연애'], 'A Korean man in his early 20s walking with a partner in different outfits, easy pace, evening'),
  ('romance', '생일 서프라이즈, 부담임?', '난 미리 말한 식사가 깜짝 이벤트보다 따뜻하다고 봄. 서프라이즈파 나와봐.', '깜짝은 감동이 아니라 일정 습격일 수 있음. 좋아하는 방식부터 물음.', ARRAY['생일','서프라이즈','연애'], 'A Korean woman in her early 20s arriving at a reserved small table, partner already there, calm happy'),
  ('romance', '연애 중 혼자 여행, 돼도 됨?', '난 각자 여행 하루가 연애를 덜 지치게 한다고 봄. 같이 가야 신뢰라는 사람 반박해봐.', '혼자 여행은 거리가 아님. 일정만 공유하면 기다림이 안심이 됨.', ARRAY['혼자여행','신뢰','연애'], 'A Korean man in his early 20s with a day bag at a station, sending a departure text, content'),
  ('romance', '싸움, 다음 날 다시 꺼내는 게 맞음?', '난 잠든 뒤 한 번 더 정리하는 게 재발 방지라고 봄. 지난 얘기 끄집어내지 말자는 쪽 들어와.', '다음 날 얘기는 복수 아님. 감정 빠진 한 줄이 같은 싸움을 줄임.', ARRAY['싸움','대화','연애'], 'A Korean woman in her early 20s talking quietly with a partner the next morning, mugs on the table'),
  ('romance', '호감 거절, 바로 말하는 게 매너임?', '난 없는 마음은 그 자리에서 말하는 게 예의라고 봄. 시간을 주면 덜 아프다는 사람 나와봐.', '거절은 차가움이 아니라 일정 반환임. 애매한 하루가 제일 김.', ARRAY['거절','호감','매너'], 'A Korean man in his early 20s speaking kindly and directly across a quiet table, daytime, serious gentle face')
